#include <iostream>
using namespace std;

using ll = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    if (!(cin >> n)) return 0;

    auto base = [](ll b) -> i128 {
        return (i128)3 * b * (b + 1);
    };

    ll lo = 0, hi = 1;
    while (base(hi) < n) {
        lo = hi;
        hi *= 2;
    }

    while (lo + 1 < hi) {
        ll mid = lo + (hi - lo) / 2;
        if (base(mid) < n)
            lo = mid;
        else
            hi = mid;
    }

    ll b = lo;
    ll l = b + 1;
    ll remainder = (ll)((i128)n - 1 - base(b));
    ll c = remainder / l;
    ll d = remainder % l;
    ll offset = l - 1 - d;
    ll x = 0, y = 0;

    switch (c) {
        case 0:
            x = l + offset;
            y = 2 * l - 2 * offset;
            break;
        case 1:
            x = -l + 2 * offset;
            y = 2 * l;
            break;
        case 2:
            x = -2 * l + offset;
            y = 2 * offset;
            break;
        case 3:
            x = -l - offset;
            y = -2 * l + 2 * offset;
            break;
        case 4:
            x = l - 2 * offset;
            y = -2 * l;
            break;
        case 5:
            x = 2 * l - offset;
            y = -2 * offset;
            break;
    }

    cout << x << ' ' << y << '\n';
    return 0;
}

